<?php
require_once __DIR__.'/config.php';$pageTitle='Study groups';$search=trim((string)($_GET['q']??''));$subjects=$pdo->query('SELECT id,name FROM subjects ORDER BY name')->fetchAll();$sql="SELECT g.*,s.name subject_name,u.name creator,(SELECT COUNT(*) FROM group_members gm WHERE gm.group_id=g.id) member_count";if(current_user())$sql.=",EXISTS(SELECT 1 FROM group_members gm2 WHERE gm2.group_id=g.id AND gm2.user_id=".(int)current_user()['id'].") is_member";$sql.=" FROM study_groups g LEFT JOIN subjects s ON s.id=g.subject_id JOIN users u ON u.id=g.creator_id WHERE 1=1";$args=[];if($search!==''){$sql.=" AND (g.name LIKE ? OR g.description LIKE ?)";$like='%'.$search.'%';$args=[$like,$like];}$sql.=" ORDER BY g.created_at DESC";$stmt=$pdo->prepare($sql);$stmt->execute($args);$groups=$stmt->fetchAll();
if(is_post()){require_login();verify_csrf();$gid=valid_id($_POST['group_id']??0);$action=$_POST['action']??'';$check=$pdo->prepare('SELECT id,creator_id FROM study_groups WHERE id=?');$check->execute([$gid]);$g=$check->fetch();if(!$g){set_flash('error','Group not found.');redirect('groups.php');}if($action==='join'){$pdo->prepare('INSERT IGNORE INTO group_members(group_id,user_id) VALUES(?,?)')->execute([$gid,current_user()['id']]);set_flash('success','You joined the study group.');}elseif($action==='leave'){if((int)$g['creator_id']===(int)current_user()['id'])set_flash('error','The group creator cannot leave their own group.');else{$pdo->prepare('DELETE FROM group_members WHERE group_id=? AND user_id=?')->execute([$gid,current_user()['id']]);set_flash('success','You left the study group.');}}redirect('group.php?id='.$gid);}
require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><span class="eyebrow">LEARN BETTER TOGETHER</span><h1>Find your study circle.</h1><p>Join classmates who share your subjects, goals, and curiosity. Create a group if you cannot find the right fit.</p></div></section><div class="page-content"><div class="container"><div class="toolbar"><form class="search-form"><input type="search" name="q" value="<?= e($search) ?>" placeholder="Search groups or subjects…"><button class="btn btn-primary">Search</button></form><?php if(current_user()): ?><a class="btn btn-primary" href="group-create.php">＋ Create a group</a><?php else: ?><a class="btn btn-outline" href="login.php">Log in to create a group</a><?php endif; ?></div><?php if($groups): ?><div class="grid-3"><?php foreach($groups as $g): ?><article class="card group-card"><div class="group-top"><div class="feature-icon">👥</div><span class="tag"><?= e($g['subject_name']??'General') ?></span></div><h3><a href="group.php?id=<?= (int)$g['id'] ?>"><?= e($g['name']) ?></a></h3><p><?= e(excerpt($g['description'])) ?></p><div class="group-members"><?= (int)$g['member_count'] ?> members · Created by <?= e($g['creator']) ?></div><div class="card-actions"><a class="btn btn-outline btn-small" href="group.php?id=<?= (int)$g['id'] ?>">View group</a><?php if(current_user()): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="group_id" value="<?= (int)$g['id'] ?>"><?php if(!empty($g['is_member'])): ?><input type="hidden" name="action" value="leave"><button class="btn btn-outline btn-small">Leave</button><?php else: ?><input type="hidden" name="action" value="join"><button class="btn btn-primary btn-small">Join group</button><?php endif; ?></form><?php endif; ?></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><div class="empty-icon">👥</div><h3>No study groups yet</h3><p>Start a group around a subject or study goal and invite others to join.</p><?php if(current_user()): ?><a class="btn btn-primary" href="group-create.php">Create the first group</a><?php endif; ?></div><?php endif; ?></div></div><?php require __DIR__.'/includes/footer.php';?>
